#include <stdio.h>
#include <math.h>
typedef struct{float x,y,z;}V;
static V v(float a,float b,float c){V r={a,b,c};return r;}
static V ad(V a,V b){return v(a.x+b.x,a.y+b.y,a.z+b.z);}
static V sb(V a,V b){return v(a.x-b.x,a.y-b.y,a.z-b.z);}
static V ml(V a,float s){return v(a.x*s,a.y*s,a.z*s);}
static float dt(V a,V b){return a.x*b.x+a.y*b.y+a.z*b.z;}
static V nr(V a){float l=(float)sqrt((double)dt(a,a));return v(a.x/l,a.y/l,a.z/l);}
static V C={0,-0.5f,-5};
/* returns t or -1 on miss; sets normal */
static float sph(V o,V d,V*n){
  V oc=sb(o,C);float a=dt(d,d),b=2*dt(oc,d),c=dt(oc,oc)-1.0f;
  float D=b*b-4.0f*a*c;if(D<0)return -1;
  float t=(float)((-(double)b-sqrt(D))/(double)(a+a));
  if(t<0.001f){t=(float)((-(double)b+sqrt(D))/(double)(a+a));if(t<0.001f)return -1;}
  if(n)*n=nr(sb(ad(o,ml(d,t)),C));return t;
}
int main(){
  int W=2400,H=1800,i,j;
  V L=nr(v(1,1,-1)),O=v(0,0,0);
  float vw=(float)W/(float)H*2.0f;
  V hz=v(vw,0,0),vt=v(0,2,0);
  V ll=sb(sb(sb(O,ml(hz,0.5f)),ml(vt,0.5f)),v(0,0,1));
  FILE*f=fopen("reconstructed.ppm","w");
  fprintf(f,"P3\n%d %d\n255\n",W,H);
  for(j=0;j<H;j++)for(i=0;i<W;i++){
    float u=(float)i/(float)(W-1),w=(float)j/(float)(W>0?H-1:1);
    V d=nr(ad(ll,ad(ml(hz,u),sb(ml(vt,1.0f-w),O)))),col,n,p;
    float ts=sph(O,d,&n),tp=-1;int s=0,h=1;
    if(!(fabsf(d.y)<1e-4f)){tp=(-1.5f-O.y)/d.y;if(tp<0.001f)tp=-1;}
    if(ts>=0&&(tp<0||tp>ts)){s=1;p=ad(O,ml(d,ts));}
    else if(tp>=0){p=ad(O,ml(d,tp));n=v(0,1,0);}
    else{float t=0.5f*(d.y+1.0f);col=ad(ml(v(1,1,1),1.0f-t),ml(v(0.5f,0.7f,1.0f),t));h=0;}
    if(h){
      float df=(float)fmax((double)dt(n,L),0.0);
      if(sph(ad(p,ml(n,0.001f)),L,0)>=0)df=0;
      df=(1.0f-0.2f)*df+0.2f;
      if(s)col=ml(v(1,0.2f,0.2f),df);
      else{float g=(((int)(floor(p.x)+floor(p.z)))&1)==0?0.9f:0.4f;col=ml(v(g,g,g),df);}
    }
    float c[3]={col.x,col.y,col.z};
    for(int k=0;k<3;k++){float x=(float)fmin(fmax((double)c[k],0.0),1.0);fprintf(f,"%d%c",(int)(255.99f*x),k<2?' ':'\n');}
  }
  fclose(f);return 0;
}

